-- Maria Martinez (profileID=13) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Maria Martinez phrasings

SELECT p.argumentID, p.phrasingID, 13, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 13
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 13 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=13 AND targArgID IN (67,68,80,90,104,107,110,124,125,126,127,128,129,130,134,135,136,137,138,139,142,145,153,155,161,197,199,201,217,226,400,401,405,416,428,504,560,561,567,568,574,578,579,580,604,605,606,607,609,611,612,615,616,617,619,785,844,902,964,965);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 13
SET pe.active = o.acceptance
WHERE pe.profileID = 13;

SELECT 'Done: endorsements for profileID=13' AS status;